(function(){
 'use strict';
 const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const number=new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}),integer=new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0});
 const money=v=>Number.isFinite(v)?number.format(v)+' ₽':'—',percent=v=>Number.isFinite(v)?number.format(v)+'%':'—';
 window.createPultEconomics=function(){
  let model=null,page=1;const size=20;
  document.querySelector('.ins-two').insertAdjacentHTML('afterend',`<section class="panel eco-panel" id="economics"><div class="panel-heading"><div><span class="eyebrow">ОТ ОБОРОТА К РЕЗУЛЬТАТУ</span><h2>Прибыль и экономика</h2><p>Две версии: наш расчёт по Ozon и управленческий отчёт TrueStats</p><p id="eco-period"></p></div><span class="pill muted" id="eco-status">Готовим расчёт</span></div><div id="eco-notice" class="eco-notice" role="status"></div><div class="eco-metrics" id="eco-metrics"></div><div class="eco-equation" id="eco-equation"></div><details class="eco-method"><summary>Как рассчитаны прибыль и себестоимость</summary><p>Оценка прибыли = итог всех начислений Ozon после удержаний − себестоимость реализованных единиц с учётом возвратов. Комиссия, логистика, рекламные удержания и другие начисления уже входят в итог Ozon и повторно не вычитаются. Баллы за скидки и софинансирование повторно не прибавляются.</p><p>Количество определяется только когда сумма реализации делится на цену за единицу из того же начисления без остатка. Это расчётное количество, а не количество заказанных товаров. Возврат уменьшает количество и восстанавливает себестоимость по текущей цене. История закупок, повреждения возвращённого товара и списания вне Ozon не учтены.</p><p>Результат по SKU включает только начисления, которые Ozon связал с этим SKU. Общие начисления и удержания магазина учитываются в полном результате магазина и не распределяются произвольно по товарам. При нехватке количества или себестоимости полный результат не показывается. Маржинальность = результат / реализация × 100%; при реализации ≤ 0 она не рассчитывается.</p><p>Расчёт в рублях. Налоги, зарплаты, аренда, упаковка и другие внешние расходы пока не внесены. Себестоимость берётся из текущего снимка Ozon, поэтому это управленческая оценка, а не бухгалтерская чистая прибыль.</p></details><div class="eco-subheading"><h3>Экономика магазинов</h3><p>За период, выбранный в управленческой сводке</p></div><div class="table-wrap"><table><thead><tr><th>Магазин</th><th class="numeric">Реализация</th><th class="numeric">Удержания Ozon</th><th class="numeric">Себестоимость</th><th class="numeric">Прибыль до налогов</th><th class="numeric">Маржинальность</th><th>Полнота</th></tr></thead><tbody id="eco-store-rows"></tbody></table></div><div class="eco-subheading"><h3>Экономика товаров</h3><p>Результат по SKU до общих расходов магазина</p></div><div class="product-controls"><label class="search-label">Найти товар<input type="search" id="eco-search" placeholder="Название, артикул, SKU или магазин"></label><label>Показать<select id="eco-filter"><option value="">Все товары</option><option value="negative">Отрицательный результат</option><option value="positive">Положительный результат</option><option value="missing">Не хватает данных</option></select></label><label>Сортировка<select id="eco-sort"><option value="profit">По результату ↓</option><option value="loss">По результату ↑</option><option value="margin">По маржинальности ↓</option><option value="realized">По реализации ↓</option></select></label></div><div class="table-wrap"><table><thead><tr><th>Товар / магазин</th><th class="numeric">Реализация</th><th class="numeric">Единиц</th><th class="numeric">Себестоимость</th><th class="numeric">Удержания по SKU</th><th class="numeric">Результат по SKU</th><th class="numeric">На единицу / маржа</th><th>Проверка</th></tr></thead><tbody id="eco-product-rows"></tbody></table></div><div class="pagination"><span id="eco-count"></span><div><button class="button secondary" id="eco-prev" aria-label="Предыдущая страница экономики">←</button><span id="eco-page"></span><button class="button secondary" id="eco-next" aria-label="Следующая страница экономики">→</button></div></div></section>`);
  const comparisonView=window.createPultProfitComparison?.();
  const card=(name,value,note,tone='')=>'<div class="eco-metric '+tone+'"><span>'+name+'</span><strong>'+value+'</strong><small>'+note+'</small></div>';
  function renderProducts(){
   if(!model)return;
   const query=$('eco-search').value.trim().toLocaleLowerCase('ru-RU'),filter=$('eco-filter').value,sort=$('eco-sort').value;
   const rows=model.products.filter(p=>(!query||[p.name,p.offerId,p.sku,p.storeName].join(' ').toLocaleLowerCase('ru-RU').includes(query))&&(!filter||filter==='negative'&&p.profit!==null&&p.profit<0||filter==='positive'&&p.profit!==null&&p.profit>0||filter==='missing'&&!p.costComplete));
   const field=sort==='margin'?'margin':sort==='realized'?'realized':'profit';rows.sort((a,b)=>a[field]===null?b[field]===null?0:1:b[field]===null?-1:(a[field]-b[field])*(sort==='loss'?1:-1));
   page=Math.max(1,Math.min(page,Math.ceil(rows.length/size)||1));
   $('eco-product-rows').innerHTML=rows.slice((page-1)*size,page*size).map(p=>'<tr><td>'+(p.key?'<a class="product-title" href="/manage.html?product='+encodeURIComponent(p.key)+'" title="'+esc(p.name)+'">'+esc(p.name)+'</a>':'<span class="product-title">'+esc(p.name)+'</span>')+'<span class="sub">'+esc(p.storeName)+' · SKU '+esc(p.sku)+'</span><span class="sub">'+esc(p.offerId)+'</span></td><td class="numeric">'+money(p.realized)+'</td><td class="numeric">'+integer.format(p.netUnits)+'<span class="sub">Продажи '+integer.format(p.soldUnits)+' / возвраты '+integer.format(p.returnedUnits)+'</span>'+(p.unknownUnitRows?'<span class="eco-warning">Есть неопределённое количество</span>':'')+'</td><td class="numeric">'+money(p.cogs)+'<span class="sub">'+money(p.unitCost)+' / ед.</span></td><td class="numeric">'+money(p.ozonDeductions)+'</td><td class="numeric '+(p.profit===null?'':p.profit<0?'eco-negative':'eco-positive')+'"><strong>'+money(p.profit)+'</strong></td><td class="numeric">'+money(p.perUnit)+'<span class="sub">'+percent(p.margin)+'</span></td><td>'+(p.costComplete?'<span class="pill">Рассчитано</span>':'<span class="pill warn">'+(p.unknownUnitRows?'Проверить количество':p.missingCost?'Нет себестоимости':'Неполный период')+'</span>')+'</td></tr>').join('')||'<tr><td colspan="8" class="empty">Нет товаров по выбранным условиям.</td></tr>';
   $('eco-count').textContent='Найдено '+integer.format(rows.length)+' из '+integer.format(model.products.length)+' SKU';$('eco-page').textContent=page+' / '+(Math.ceil(rows.length/size)||1);$('eco-prev').disabled=page===1;$('eco-next').disabled=page*size>=rows.length;
  }
  for(const id of ['eco-search','eco-filter','eco-sort'])$(id).addEventListener(id==='eco-search'?'input':'change',()=>{page=1;renderProducts()});
  $('eco-prev').onclick=()=>{page--;renderProducts()};$('eco-next').onclick=()=>{page++;renderProducts()};
  return {render(report){
   model=report.economics;
   comparisonView?.render(report);
   const date=value=>new Date(value+'T12:00:00Z').toLocaleDateString('ru-RU'),today=new Date(report.generatedAt).toLocaleDateString('en-CA',{timeZone:'Europe/Moscow'}),preliminary=report.current.to>=today;
   $('eco-period').textContent='Период: '+date(report.current.from)+' — '+date(report.current.to)+(preliminary?' · показатели текущего дня предварительные':' · завершённый период');
   if(!model){$('eco-notice').textContent='Расчёт экономики появится после обновления сервера.';return}
   $('eco-status').className='pill '+(model.complete?'':'warn');$('eco-status').textContent=model.complete?'Расчёт завершён':'Неполные данные';
   const issues=[!model.covered?'Финансовый период загружен не полностью':'',model.missingCostSkus?integer.format(model.missingCostSkus)+' SKU без себестоимости':'',model.unknownUnitRows?integer.format(model.unknownUnitRows)+' строк с неопределённым количеством':'',model.unmappedSaleRows?integer.format(model.unmappedSaleRows)+' строк реализации без SKU':''].filter(Boolean);
   $('eco-notice').textContent=issues.length?'Полная прибыль пока не определена: '+issues.join(' · ')+'. Ниже — результат только рассчитанных SKU и список пробелов.':'Учтены все доступные начисления выбранных магазинов и себестоимость.'+(preliminary?' Сегодняшние показатели предварительные и меняются с загрузками Ozon.':' Период завершён.');
   $('eco-metrics').innerHTML=card('Оценка прибыли до налогов',money(model.profit),model.complete?'После всех начислений Ozon и себестоимости':'Нужны полные данные по количеству и себестоимости',model.profit!==null?(model.profit<0?'negative':'positive'):'')+card('Результат рассчитанных SKU',money(model.knownContribution),integer.format(model.calculatedSkus)+' из '+integer.format(model.totalSkus)+' SKU · до общих расходов магазина')+card('Учтено себестоимости',money(model.knownCogs),model.complete?'Продажи минус возвраты · текущие закупочные цены':'Только рассчитанная часть · текущие закупочные цены')+card('Маржинальность магазина',percent(model.margin),'Прибыль до налогов / реализация');
   $('eco-equation').innerHTML='<span>Реализация <b>'+money(model.realized)+'</b></span><span>− удержания Ozon <b>'+money(model.ozonDeductions)+'</b></span><span>− себестоимость <b>'+money(model.cogs)+'</b></span><span>= прибыль до налогов <b>'+money(model.profit)+'</b></span><small>Общие начисления / удержания без SKU: '+money(model.sharedNet)+' · входят в полный результат магазина.</small>';
   $('eco-store-rows').innerHTML=model.stores.map(s=>'<tr><td>'+esc(s.name)+'</td><td class="numeric">'+money(s.realized)+'</td><td class="numeric">'+money(s.ozonDeductions)+'</td><td class="numeric">'+money(s.cogs)+(s.cogs===null?'<span class="sub">Учтено '+money(s.knownCogs)+'</span>':'')+'</td><td class="numeric '+(s.profit===null?'':s.profit<0?'eco-negative':'eco-positive')+'"><strong>'+money(s.profit)+'</strong></td><td class="numeric">'+percent(s.margin)+'</td><td><span class="pill '+(s.complete?'':'warn')+'">'+s.calculatedSkus+' / '+s.totalSkus+' SKU</span></td></tr>').join('');
   renderProducts();
  }};
 };
})();
